import { announceBareHost, hostCapability } from "./registry.js";
function text(message) {
  return typeof message === "string" ? message : typeof message === "function" ? "[toast]" : String(message);
}
const consoleToast = Object.assign(
  (message) => {
    announceBareHost("toast", "notices go to the console");
    console.info(`[rich-content] ${text(message)}`);
    return Date.now();
  },
  {
    success: (m) => {
      announceBareHost("toast", "notices go to the console");
      console.info(`[rich-content] \u2713 ${text(m)}`);
      return Date.now();
    },
    error: (m) => {
      announceBareHost("toast", "notices go to the console");
      console.error(`[rich-content] ${text(m)}`);
      return Date.now();
    },
    info: (m) => {
      announceBareHost("toast", "notices go to the console");
      console.info(`[rich-content] ${text(m)}`);
      return Date.now();
    },
    warning: (m) => {
      announceBareHost("toast", "notices go to the console");
      console.warn(`[rich-content] ${text(m)}`);
      return Date.now();
    },
    loading: (m) => {
      announceBareHost("toast", "notices go to the console");
      console.info(`[rich-content] \u2026 ${text(m)}`);
      return Date.now();
    },
    dismiss: () => {
    }
  }
);
function current() {
  return hostCapability("toast") ?? consoleToast;
}
const toast = Object.assign(
  ((message, data) => current()(message, data)),
  {
    success: ((m, d) => current().success(m, d)),
    error: ((m, d) => current().error(m, d)),
    info: ((m, d) => current().info(m, d)),
    warning: ((m, d) => current().warning(m, d)),
    loading: ((m, d) => current().loading(m, d)),
    dismiss: ((id) => current().dismiss(id))
  }
);
export {
  toast
};
